class Singleton:
    private static instance = null

    // constructor is private — no outside "new"
    private constructor():
        // expensive setup happens once here

    static method getInstance():
        if instance == null:
            instance = new Singleton()
        return instance

// usage
config = Singleton.getInstance()
sameConfig = Singleton.getInstance()
// config == sameConfig, same object
```

```text
interface Button:
    method render()

interface Checkbox:
    method render()

// family: dark theme
class DarkButton implements Button:
    method render(): print("dark button")
class DarkCheckbox implements Checkbox:
    method render(): print("dark checkbox")

// family: light theme
class LightButton implements Button:
    method render(): print("light button")
class LightCheckbox implements Checkbox:
    method render(): print("light checkbox")

interface UiFactory:
    method createButton(): Button
    method createCheckbox(): Checkbox

class DarkUiFactory implements UiFactory:
    method createButton(): Button: return new DarkButton()
    method createCheckbox(): Checkbox: return new DarkCheckbox()

// usage — one factory, a matching family every time
factory = new DarkUiFactory()
button = factory.createButton()
checkbox = factory.createCheckbox()
```
